    /// Converts the cell midpoint to the frozen legacy polar address.
    public static func polarCell(
        atCenterOf cell: MetricGridCell,
        in grid: MetricSquareGrid
    ) throws -> PolarMetricGridCell {
        try address(of: cell, in: grid, bounds: .production)
    }

    internal static func address(
        of cell: MetricGridCell,
        in grid: MetricSquareGrid,
        bounds: BoundSet
    ) throws -> PolarMetricGridCell {
        let centimeterGrid: Int
        do {
            centimeterGrid = try LegacyLatticeMigration.centimeterGrid(grid)
        } catch LegacyLatticeMigration.MigrationError.nonIntegerCentimeterGrid(let size) {
            throw AddressError.nonIntegerCentimeterGrid(size)
        }

        guard cell.row >= 0 else {
            throw AddressError.rowNotInFrontHalfPlane(column: cell.column, row: cell.row)
        }

        guard let x = checkedTwicePlusOne(cell.column),
              let y = checkedTwicePlusOne(cell.row)
        else {
            throw AddressError.outsideValueRange(column: cell.column, row: cell.row)
        }
        let xCentimeterProduct = x.multipliedReportingOverflow(by: centimeterGrid)
        let yCentimeterProduct = y.multipliedReportingOverflow(by: centimeterGrid)
        guard !xCentimeterProduct.overflow, !yCentimeterProduct.overflow else {
            throw AddressError.outsideValueRange(column: cell.column, row: cell.row)
        }
        let xCentimeters = xCentimeterProduct.partialValue
        let yCentimeters = yCentimeterProduct.partialValue

        let xSquared = x.multipliedReportingOverflow(by: x)
        let ySquared = y.multipliedReportingOverflow(by: y)
        guard !xSquared.overflow, !ySquared.overflow else {
            throw AddressError.outsideValueRange(column: cell.column, row: cell.row)
        }
        let squared = xSquared.partialValue.addingReportingOverflow(ySquared.partialValue)
        guard !squared.overflow else {
            throw AddressError.outsideValueRange(column: cell.column, row: cell.row)
        }

        let physicalXSquared = xCentimeters.multipliedReportingOverflow(by: xCentimeters)
        let physicalYSquared = yCentimeters.multipliedReportingOverflow(by: yCentimeters)
        guard !physicalXSquared.overflow, !physicalYSquared.overflow else {
            throw AddressError.outsideValueRange(column: cell.column, row: cell.row)
        }
        let physicalSum = physicalXSquared.partialValue.addingReportingOverflow(physicalYSquared.partialValue)
        let limitSquared = 16_380.multipliedReportingOverflow(by: 16_380)
        guard !physicalSum.overflow, !limitSquared.overflow,
              physicalSum.partialValue <= limitSquared.partialValue
        else {
            throw AddressError.outsideValueRange(column: cell.column, row: cell.row)
        }

        let ring = try exactRing(squared: squared.partialValue, cell: cell)
        let k = exponent(forRing: ring)
        let j = try angleIndex(
            x: x, y: y, k: k, cell: cell, bounds: bounds
        )
        return PolarMetricGridCell(ring: ring, angularIndex: j + (2 << k))
    }

    private static func checkedTwicePlusOne(_ value: Int) -> Int? {
        let doubled = value.multipliedReportingOverflow(by: 2)
        guard !doubled.overflow else { return nil }
        let result = doubled.partialValue.addingReportingOverflow(1)
        return result.overflow ? nil : result.partialValue
    }

    private static func exactRing(squared: Int, cell: MetricGridCell) throws -> Int {
        var low = 0
        // Der **alte** Polarring ist `floor(radius / cellSize)`. Er ist nicht
        // der Gitterring: bei 1-cm-Raster reicht er bis 8190, nicht bis 1638.
        // Die frühere Obergrenze 1638 hat solche Zellen still auf 1638
        // geklemmt und eine falsche Adresse geliefert statt abzulehnen —
        // gemessen am 28.09.2026 an (0, 2000) bei 1 cm: Altweg (2000, 8192),
        // geklemmt (1638, 4096).
        // 8190 ist exakt: der Radius ist auf 8190 cm begrenzt und die
        // Rasterweite ist mindestens 1 cm.
        var high = 8_190
        while low < high {
            let middle = (low + high + 1) / 2
            let nSquared = middle.multipliedReportingOverflow(by: middle)
            guard !nSquared.overflow else {
                throw AddressError.outsideValueRange(column: cell.column, row: cell.row)
            }
            let boundary = 4.multipliedReportingOverflow(by: nSquared.partialValue)
            guard !boundary.overflow else {
                throw AddressError.outsideValueRange(column: cell.column, row: cell.row)
            }
            if boundary.partialValue <= squared { low = middle } else { high = middle - 1 }
        }
        return low
    }

    /// `k` mit `2^k = angularDivisor(forRing:)`. Der Vertragsexponent wird
    /// **nicht** neu gerechnet: er steht in `LegacyLatticeMigration` und
    /// stand dort bis heute in drei Kopien. Eine vierte hier hätte die
    /// kartesische Adresse von der polaren abdriften lassen können.
    private static func exponent(forRing ring: Int) -> Int {
        LegacyLatticeMigration.angularDivisor(forRing: ring).trailingZeroBitCount
    }

    private static func angleIndex(
        x: Int, y: Int, k: Int, cell: MetricGridCell, bounds: BoundSet
    ) throws -> Int {
        let half = 1 << k
        let maxJ = half
        // Keine Vorabkürzung für die Diagonalen. Sie wurden hier zweimal
        // entschieden — einmal vorab und einmal im Zweig `middle == ±half/2`
        // unten. Dadurch erreichte der Gleichheitsfall den unteren Zweig nie,
        // und dessen `<=` war gegen `<` ununterscheidbar: die Gegenprobe
        // „Diagonale dem kleineren Index" lief dort ins Leere. Jetzt
        // entscheidet die Suche beide Diagonalen an genau einer Stelle.
        //
        // Ein früher `if x == 0 { return 0 }` stand ebenfalls hier. Er ist
        // unerreichbar: `x = 2·column + 1` ist immer ungerade. Der Revisor
        // hält die 0°- und ±90°-Grenzen aus genau diesem Grund für
        // ausgeschlossen.

        let effectiveBounds = bounds == .forcedGap
            ? nil
            : Optional(lowerNumerators)
        var low = -maxJ
        var high = maxJ
        while low < high {
            let middle = (low + high + 1) / 2
            if middle == 0 {
                if 0 <= x { low = middle } else { high = middle - 1 }
                continue
            }
            if middle == maxJ {
                high = middle - 1
                continue
            }
            if middle == -maxJ {
                low = middle
                continue
            }
            if middle == half / 2 || middle == -half / 2 {
                let trueAtOrAbove = middle > 0 ? y <= x : -y <= x
                if trueAtOrAbove { low = middle } else { high = middle - 1 }
                continue
            }
            guard let table = effectiveBounds,
                  abs(middle) < half
            else {
                throw AddressError.unclassifiableAngle(column: cell.column, row: cell.row)
            }
            // Die Tabelle deckt nur die erzeugten Exponenten ab. Ohne diese
            // Prüfung wäre `table[k]` ein Indexfehler und damit ein Absturz
            // statt einer benannten Ablehnung. Bis eben war sie nur deshalb
            // nie nötig, weil der Ring auf 1638 geklemmt wurde.
            guard k < table.count else {
                throw AddressError.angularTableDoesNotCover(
                    exponent: k, column: cell.column, row: cell.row
                )
            }
            let positive = table[k][abs(middle) - 1]

            let lower = middle > 0 ? positive : -positive - 2
            let upper = middle > 0 ? positive + 2 : -positive
            let lhsUpper = upper.multipliedReportingOverflow(by: y)
            let lhsLower = x.multipliedReportingOverflow(by: denominator)
            let rhsLower = lower.multipliedReportingOverflow(by: y)
            guard !lhsUpper.overflow, !lhsLower.overflow, !rhsLower.overflow else {
                throw AddressError.unclassifiableAngle(column: cell.column, row: cell.row)
            }
            if lhsUpper.partialValue <= lhsLower.partialValue {
                low = middle
            } else if lhsLower.partialValue < rhsLower.partialValue {
                high = middle - 1
            } else {
                throw AddressError.unclassifiableAngle(column: cell.column, row: cell.row)
            }
        }
        return low
    }
}
